operations.query:
mutation UpdateStoppedTeamRunModelConfigs($input: UpdateStoppedTeamRunModelConfigsInput!) {
  updateStoppedTeamRunModelConfigs(input: $input) {
    success
    outcome
    message
    isActive
    editability {
      editable
      reason
      __typename
    }
    canonicalExecutionTree
    fieldErrors {
      path
      message
      __typename
    }
    __typename
  }
}
